const APPROVER = 'approver';
const SETUP = 'setup';
const CRON = 'cron';
const FEE = 'fee';
const WAIT_RECEIPT = {waitReceipt: true};

function isProd() {
  return ENV === 'prod';
}

function nodeName(name) {
  return `${name} — ${ENV}`;
}

function success(obj) {
  console.log(JSON.stringify(obj));
  return obj;
}

function parseBool(str) {
  return str === 'true';
}

function issueAsset(symbol, value, name, description, baseUnit, isReissuable, nextOwner, icapName) {
  const callResult = {};
  const switches = isProd() ? [
    callFunction(etokSwitches, [
      { name: 'issue', params: [symbol, isReissuable] },
      { name: 'transferWithReference', params: [symbol] },
      { name: 'revoke', params: [symbol] },
      { name: 'changeOwnership', params: [symbol] },
      { name: 'allowances', params: [symbol] },
      { name: 'icap', params: [symbol] },
    ], callResult),
    safeTransactionFunction(etok.setSwitch, [() => callResult.issue, true], address),
    safeTransactionFunction(etok.setSwitch, [() => callResult.transferWithReference, true], address),
    safeTransactionFunction(etok.setSwitch, [() => callResult.revoke, true], address),
    safeTransactionFunction(etok.setSwitch, [() => callResult.changeOwnership, true], address),
    safeTransactionFunction(etok.setSwitch, [() => callResult.allowances, true], address),
    safeTransactionFunction(etok.setSwitch, [() => callResult.icap, true], address)
  ] : [];
  return safeTransactions([
    callFunction(etok, [{ name: 'isCreated', params: [symbol] }], callResult),
    asyncFunction((resolve, reject) => {
      if (callResult.isCreated) {
        return reject(`Currency ${symbol} is already issued.`);
      }
      resolve();
    })
  ].concat(switches).concat([
    safeTransactionFunction(etok.issueAsset, [symbol, value, name, description, baseUnit, isReissuable], address),
    safeTransactionFunction(icap.registerAsset, [icapName, symbol], address)
  ]));
}

function finalizeAssetIssuance(symbol, nextOwner) {
  return safeTransactionFunction(etok.changeOwnership, [symbol, nextOwner], address, WAIT_RECEIPT);
}

function transferAssetsToNextOwner(symbol, value, nextOwner) {
  return web3.toBigNumber(value).eq(0) ? syncFunction(() => {}) : safeTransactionFunction(etok.transferWithReference, [nextOwner, value, symbol, 'Asset issuance and deployment'], address);
}

